def verify_isbn(isbn: str) -> str:
    if '-' not in isbn or len(isbn) != 17:
        return "Invalid ISBN format"

    if isbn[-1].upper() == 'X':
        assign_value = 10
    else:
        assign_value = ord(isbn[-1]) - ord('0')

    isbn = isbn[:-1]

    product = 0
    for i in range(len(isbn)):
        # Digits are multiplied by their weights, from right to left, and then the products are summed
        product += (10 - i) * int(isbn[i]) * assign_value

    dividend, modulo = divmod(product + 1, 11)

    if modulo == 0:
        return "Right"
    else:
        corrected_product = (dividend + 1) * 11 - (product + 1)
        return isbn[:len(isbn) - 1] + str(corrected_product % 11)
