def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M < K + D or N < L + D:
        return 'Error: Not enough rows or columns to accommodate aisles without crossings'

    # Initialize the number of axes to 2 (if any lines have intersections with a previous row or column)
    axes = 2

    for i in range(M):
        for L in range(1, L + 1):
            if is_diagonal(i, i + L, chatting_pairs):
                axes += 1
        if M - 1 - i < K + D:
            break

    for j in range(N):
        for L in range(1, L + 1):
            if is_diagonal(j, j + L, chatting_pairs):
                axes += 1
        if N - 1 - j < K + D:
            break

    aisle_positions = []
    for i in range(M):
        for j in range(N):
            for L in range(1, M + N - i):
                if is_diagonal(i, j, L, chatting_pairs):
                    aisle_positions.append((i, j))

    # Get the optimal row and column indices for the aisles
    best_y, best_x = get_optimal_aisle_positions(aisle_positions, K, L, D, chatting_pairs)

    return f"{best_y} {best_x}"

def is_diagonal(i0, i1, j0, j1, chatting_pairs):
    for (x0, y0, x1, y1) in chatting_pairs:
        if abs(x0 - x1) + abs(y0 - y1) <= i1 - i0 and (x0 - x1) != (y0 - y1):
            return True
    return False

def get_optimal_aisle_positions(aisle_positions, K, L, D, chatting_pairs):
    # Find the best row and column indices
    best_y = None
    best_x = None
    max_separation = 0

    for y in range(M):
        for x in range(N):
            for L in range(1, M + N - x):
                if is_diagonal(y, y + L, x, x + L, chatting_pairs):
                    separation = L + D
                    if separation > max_separation:
                        max_separation = separation
                        best_y = y
                        best_x = x

    return best_y, best_x
