def max_energy(beads):
    n = len(beads)

    # Initialize a 2D table to store the maximum energy for each subproblem
    dp = [[0] * n for _ in range(n)]

    # For each subproblem of length 2, mark when two adjacent beads can be merged
    for i in range(n):
        if beads[i] == beads[(i + 1) % n]:
            dp[i][i + 1] = beads[i] * beads[(i + 1) % n]

    # Fill the dp table for other subproblems
    for sub_len in range(3, n + 1):
        for start in range(n - sub_len + 1):
            end = start + sub_len - 1
            if beads[start] == beads[(end + 1) % n]:
                dp[start][end] = beads[start] * beads[(end + 1) % n] + dp[start + 1][end]
            elif beads[start] == beads[end]:
                dp[start][end] = beads[start] * beads[end] + dp[start + 1][end - 1]

    # The maximum energy release is the maximum value in the last row of the dp table
    return dp[0][n - 1]
```

