from collections import deque

def generate_numbers(n, rules):
    original_digits = set(str(n))
    generated_numbers = {int(digit) for digit in original_digits}

    queue = deque()
    for digit in original_digits:
        for rule in rules:
            transformed_digit = str(int(digit) + rule[0])
            if int(transformed_digit) not in original_digits or int(transformed_digit) in generated_numbers:
                continue
            queue.append(int(transformed_digit))
            generated_numbers.add(int(transformed_digit))

    while queue:
        current_digit = queue.popleft()
        for rule in rules:
            transformed_digit = str(current_digit + rule[0])
            if int(transformed_digit) not in original_digits or int(transformed_digit) in generated_numbers:
                continue
            generated_numbers.add(int(transformed_digit))
            queue.append(int(transformed_digit))

    return len(generated_numbers)
