def calculate_arrangements(n, m, a) -> int:
    if n > m:
        return 0

    mod = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(0, m + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= a[i - 1]:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - a[i - 1]]) % mod

