def vigenere_decrypt(key: str, ciphertext: str) -> str:
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = ''
    length = len(key)
    for i in range(len(ciphertext)):
        row = alphabet[(ord(key[i % length]) - ord('a')) % 26]
        row_offset = 0
        for char in ciphertext[i]:
            if char in alphabet:
                shift = alphabet.index(row[row_offset])
                if char.islower():
                    result += alphabet[(ord(char) - ord('a') - shift) % 26].upper()
                else:
                    result += alphabet[(ord(char) - ord('a') + shift) % 26]
                row_offset = (row_offset + 1) % len(row)
            else:
                result += char
    return result
```

